function replaceTerms(text) {
	const terms = [...INPUT_TERMS.keys()].sort((a, b) => b.length - a.length);
	let out = text;
	for (const term of terms) {
		const folded = foldYo(term);
		const pattern = new RegExp(`(^|[^\\p{L}\\p{N}_])${folded.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(?=$|[^\\p{L}\\p{N}_])`, "giu");
		out = out.replace(pattern, (_, lead) => `${lead}${INPUT_TERMS.get(term)}`);
	}
	return out;
}

// Russians commonly type "е" instead of "ё"; fold both sides so either matches.
function foldYo(value) {
	return value.replace(/ё/g, "е").replace(/Ё/g, "Е");
}

export function translateInput(text) {
	if (typeof text !== "string" || !text) return text;
	const foldedEarly = foldYo(text.normalize("NFC"));

	for (const [pattern, replacement] of WHOLE_INPUT) {
		const foldedPattern = new RegExp(foldYo(pattern.source), pattern.flags);
		if (foldedPattern.test(foldedEarly)) {
			return typeof replacement === "function" ? replacement(foldedEarly) : replacement;
		}
	}

	const names = protectProperNames(text);
	let out = foldYo(names.text.normalize("NFC"));

	for (const [pattern, replacement] of INPUT_PHRASES) {
		let boundaryIndex = 0;
		const unicodePattern = new RegExp(
			foldYo(pattern.source).replace(/\\b/g, () =>
				boundaryIndex++ % 2 === 0
					? "(?<![\\p{L}\\p{N}_])"
					: "(?![\\p{L}\\p{N}_])",
			),
			pattern.flags,
		);
		out = out.replace(unicodePattern, replacement);
	}
	out = replaceTerms(out);
	return names.restore(out.replace(/\s+/g, " ").trim());
}
